const uor01Text = $('Extract UOR-01 Text').first().json.data || '';
const uor03Text = $('Extract UOR-03 Text').first().json.data || '';
const uor04Text = $('Extract UOR-04 Text').first().json.data || '';
const uor05Text = $('Extract UOR-05 Text').first().json.data || '';
const uor06Text = $('Extract UOR-06 Text').first().json.data || '';
const uor07Text = $('Extract UOR-07 Text').first().json.data || '';
const uor08Text = $('Extract UOR-08 Text').first().json.data || '';
const uor09Text = $('Extract UOR-09 Text').first().json.data || '';

function parseLines(text) {
  const out = []; let failures = 0;
  text.split('\n').filter((l) => l.trim().length > 0).forEach((line) => {
    try { out.push(JSON.parse(line)); } catch (e) { failures++; }
  });
  return { records: out, failures };
}

function latestByKey(records, key) {
  const map = new Map();
  records.forEach((r) => {
    const existing = map.get(r.opportunity_id);
    if (!existing || String(r[key]) > String(existing[key])) map.set(r.opportunity_id, r);
  });
  return map;
}

const uor01 = parseLines(uor01Text);
const uor03 = parseLines(uor03Text);
const uor04 = parseLines(uor04Text);
const uor05 = parseLines(uor05Text);
const uor06 = parseLines(uor06Text);
const uor07 = parseLines(uor07Text);
const uor08 = parseLines(uor08Text);
const uor09 = parseLines(uor09Text);

// UOR-01: pick latest observation per id (date_stored) -- this drives the
// "which opportunities exist" universe.
const uor01ById = latestByKey(uor01.records, 'date_stored');
const uor03ById = latestByKey(uor03.records, 'computed_at');
const uor04ById = new Map(uor04.records.map((r) => [r.opportunity_id, r])); // already unique
const uor05ById = latestByKey(uor05.records, 'computed_at');
const uor07ById = latestByKey(uor07.records, 'computed_at');
const uor08ById = latestByKey(uor08.records, 'computed_at');
const uor09ById = new Map(uor09.records.map((r) => [r.opportunity_id, r])); // already unique

// UOR-06: reverse-index member_opportunity_ids -> tag memberships.
const tagsByOppId = new Map();
uor06.records.forEach((row) => {
  (row.member_opportunity_ids || []).forEach((id) => {
    if (!tagsByOppId.has(id)) tagsByOppId.set(id, []);
    tagsByOppId.get(id).push({ tag: row.tag, frequency_count: row.frequency_count, cluster_status: row.cluster_status });
  });
});

// Real-opportunity universe: UOR-01's unique ids, excluding synthetic
// (TEST-001-style) records -- same exclusion discipline UOR-09 already uses.
const allIds = [...uor01ById.keys()].filter((id) => uor01ById.get(id).evidence?.is_synthetic !== true);

const results = allIds.map((id) => {
  const u1 = uor01ById.get(id);
  const u3 = uor03ById.get(id) || null;
  const u4 = uor04ById.get(id) || null;
  const u5 = uor05ById.get(id) || null;
  const u7 = uor07ById.get(id) || null;
  const u8 = uor08ById.get(id) || null;
  const u9 = uor09ById.get(id) || null;
  const tags = tagsByOppId.get(id) || [];

  return {
    opportunity_id: id,
    date_discovered: u1.date_discovered,
    source: u1.source,
    source_type: u1.source_type,
    category: u1.category,
    raw_signal: u1.raw_signal,
    normalized_opportunity: u1.normalized_opportunity,
    customer_problem: u1.customer_problem,
    evidence: {
      raw: u1.evidence,
      verification: u3 ? {
        corroboration_status: u3.corroboration_status,
        corroborating_opportunity_ids: u3.corroborating_opportunity_ids,
        manipulation_flag: u3.manipulation_flag,
        manipulation_reason: u3.manipulation_reason,
        low_content_flag: u3.low_content_flag,
      } : null,
    },
    evidence_confidence: {
      initial_estimate: u1.evidence_confidence,
      reconciled: u4 ? u4.evidence_confidence_v2_latest : null,
    },
    scoring_factors: u1.scoring_factors,
    final_score: {
      per_observation: u1.final_score,
      reconciled: u4 ? u4.reconciled_opportunity_score : null,
      reconciliation_status: u4 ? u4.score_reconciliation_status : null,
    },
    tools_required: {
      declared: u1.tools_required,
      matched_existing_stack: u5 ? u5.matched_stack_tools : [],
    },
    existing_capability_match: {
      status: u5 ? u5.capability_match_status : null,
      matched_domains: u5 ? u5.matched_capability_domains : [],
      fulfillment_feasible_now: u5 ? u5.fulfillment_feasible_now : null,
    },
    estimated_cost: {
      declared: u1.estimated_fulfillment_cost,
      productization_hypothesis: u9?.productization_draft?.estimated_cost ?? null,
    },
    estimated_revenue_potential: {
      declared_usd: u1.estimated_revenue_potential_usd,
      productization_hypothesis: u9?.productization_draft?.pricing_hypothesis ?? null,
    },
    action_recommendation: {
      initial: u1.action_recommendation,
      reconciled_gate_status: u9 ? u9.gate_status : null,
      productization_tier: u9 ? u9.productization_tier : null,
    },
    status: {
      pipeline_status: u1.status,
      compliance_review_required: u1.compliance_review_required,
      compliance_keywords_detected: u1.compliance_keywords_detected,
    },
    duplicates_related_opportunities: {
      declared: u1.duplicates_related_opportunities,
      corroborating_ids_from_uor03: u3 ? u3.corroborating_opportunity_ids : [],
    },
    demand_cluster: tags,
    content_opportunity: u7 ? {
      status: u7.content_opportunity_status,
      attention_potential: u7.attention_potential,
      attention_potential_score: u7.attention_potential_score,
      copyright_platform_risk_flag: u7.copyright_platform_risk_flag,
    } : null,
    service_opportunity: u8 ? {
      status: u8.service_opportunity_status,
      keywords_matched: u8.service_seeking_keywords_matched,
    } : null,
    subsequent_outcome: u1.subsequent_outcome,
    uor10_formula_version: 'uor10-v1-historical-intelligence-2026-09-10',
  };
});

const withComputedAt = results.map((r) => ({ ...r, computed_at: new Date().toISOString() }));
const fileText = withComputedAt.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    record_count: results.length,
    uor01_total_lines: uor01.records.length,
    uor01_unique_ids: uor01ById.size,
    results,
    file_text: fileText,
  },
}];

// Sequential dependency, not an independent sibling branch (Phase 1 finding):
// this node only runs after 'Write Current-State File' has already succeeded,
// because it sits after it in a single linear chain. The history log only
// ever records a snapshot of a state write that is confirmed to have actually
// happened -- current-state is authoritative; the log is a secondary,
// dependent audit trail, never the other way around.
const results = $('Build Join').first().json.results;
const stampedText = results
  .map((r) => JSON.stringify({ ...r, snapshot_taken_at: new Date().toISOString() }))
  .join('\n') + '\n';
return [{ json: { file_text: stampedText } }];
